// at the panel's x+177, y+13; 2.11 has today's Small places (panels at 58, 198 wide).
const zq_ui_rect rects_192[] =
{
    { "panel", -1, 64, ZQ_UI_KEEP, 192, ZQ_UI_KEEP },
    { "combolistscrollers", 0, 241, 205, 11, 11 },
};
